sql_generado:
SELECT COUNT(*) AS total_gatos
FROM vet_masc
WHERE masc_esp = 'gato';

SELECT masc_nom, masc_peso
FROM vet_masc
WHERE masc_peso > 30;

SELECT due_nom
FROM vet_duenos
WHERE due_ciu = 'Antigua';

SELECT cons_id, cons_costo
FROM vet_cons
WHERE cons_motivo = 'emergencia' AND cons_costo < 500;

SELECT vet_masc.masc_nom, vet_duenos.due_nom
FROM vet_masc
JOIN vet_duenos ON vet_masc.due_id = vet_duenos.due_id;

SELECT masc_esp, COUNT(*) AS cantidad
FROM vet_masc
GROUP BY masc_esp;

SELECT masc_nom, masc_peso, masc_esp
FROM vet_masc
WHERE masc_peso > (
    SELECT AVG(masc_peso) FROM vet_masc
    WHERE masc_esp = masc_esp
);

SELECT model, seats
FROM aircraft
WHERE seats > 200;

SELECT pax_name
FROM passengers
WHERE nationality = 'Peru';

SELECT flights.flight_id, airports.airport_name
FROM flights
JOIN airports ON flights.origin = airports.airport_code;

SELECT class, COUNT(*) AS count
FROM bookings
GROUP BY class;

SELECT pax_name
FROM passengers
WHERE pax_id NOT IN (
    SELECT pax_id
    FROM bookings
);

SELECT booking_id, paid
FROM bookings
WHERE paid > (SELECT AVG(paid) FROM bookings);
